/** * Deactivate the bootstrap trigger once the application is fully remediated, so * the one-shot hook stops evaluating on every future Update Set commit. Looked * up by name, never by sys_id. A failed or partial run deliberately leaves the * trigger active so the next commit retries. */ function deactivateBootstrapTrigger() { var gr = new GlideRecord('sys_script'); gr.addQuery('name', BOOTSTRAP_TRIGGER_NAME); gr.query(); var count = 0; while (gr.next()) { if (isTrue(gr.getValue('active'))) { gr.setValue('active', false); gr.update(); count++; } } if (count > 0) { log('TRIGGER|' + BOOTSTRAP_TRIGGER_NAME + '|deactivated after successful remediation'); } else { log('TRIGGER|' + BOOTSTRAP_TRIGGER_NAME + '|already inactive or not installed'); } }
// ============================================================================ // Orchestration // ============================================================================
/** * Run every remediation in dependency order and emit the summary line. * * Order matters: the tables must exist before their fields, the fields before * the choice lists that annotate them and before the number default that lives * on one of them, and the ACLs must be linked to roles before the security * cache is flushed. * * @return {string} the summary line (also emitted through gs.info) */ function postImportRemediation() { var started = new GlideDateTime(); log('START|post-import remediation|scope_context=' + gs.getCurrentScopeName() + '|at=' + started.getDisplayValue());
